CREATE SCHEMA IF NOT EXISTS ouf_ingestion;
CREATE TABLE ouf_ingestion.ing_run(run_id uuid PRIMARY KEY,source_id text NOT NULL,bundle_id text NOT NULL,bundle_version text NOT NULL,bundle_checksum text NOT NULL,mode text NOT NULL CHECK(mode IN('FULL_SNAPSHOT','CATCH_UP','DELTA','MANAGED_ONCE','REPLAY')),state text NOT NULL CHECK(state IN('READY','PREFLIGHT','RUNNING','DRAINING','SUCCEEDED','FAILED','PAUSED')),correlation_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),updated_at timestamptz NOT NULL DEFAULT transaction_timestamp());
CREATE TABLE ouf_ingestion.ing_partition(run_id uuid NOT NULL REFERENCES ouf_ingestion.ing_run ON DELETE RESTRICT,partition_key text NOT NULL,state text NOT NULL,checkpoint_json jsonb NOT NULL DEFAULT '{}',committed_watermark_json jsonb NOT NULL DEFAULT '{}',lock_version bigint NOT NULL DEFAULT 0,PRIMARY KEY(run_id,partition_key));
CREATE TABLE ouf_ingestion.processing_attempt(attempt_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES ouf_ingestion.ing_run ON DELETE RESTRICT,source_object_id text NOT NULL,attempt_no integer NOT NULL,adapter_id text NOT NULL,bundle_version text NOT NULL,state text NOT NULL,reason_code text,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),UNIQUE(run_id,source_object_id,attempt_no));
CREATE TABLE ouf_ingestion.ing_lineage(lineage_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES ouf_ingestion.ing_run ON DELETE RESTRICT,attempt_id uuid NOT NULL REFERENCES ouf_ingestion.processing_attempt ON DELETE RESTRICT,source_object_id text NOT NULL,bundle_ref text NOT NULL,adapter_ref text NOT NULL,evidence_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp());
CREATE TABLE ouf_ingestion.handoff_outbox(handoff_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES ouf_ingestion.ing_run ON DELETE RESTRICT,lineage_id uuid NOT NULL REFERENCES ouf_ingestion.ing_lineage ON DELETE RESTRICT,idempotency_key text NOT NULL UNIQUE,payload_json jsonb NOT NULL,state text NOT NULL DEFAULT 'READY' CHECK(state IN('READY','DELIVERING','ACKED','FAILED_RETRYABLE','FAILED_TERMINAL')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT transaction_timestamp(),lease_owner text,lease_until timestamptz,downstream_receipt_ref text,acked_at timestamptz,created_at timestamptz NOT NULL DEFAULT transaction_timestamp());
CREATE INDEX handoff_claim_idx ON ouf_ingestion.handoff_outbox(state,next_attempt_at,lease_until);
CREATE TABLE ouf_ingestion.ing_quarantine(quarantine_id uuid PRIMARY KEY,run_id uuid NOT NULL REFERENCES ouf_ingestion.ing_run ON DELETE RESTRICT,attempt_id uuid REFERENCES ouf_ingestion.processing_attempt ON DELETE RESTRICT,source_object_id text,reason_code text NOT NULL,payload_ref text,evidence_ref text NOT NULL,state text NOT NULL DEFAULT 'OPEN' CHECK(state IN('OPEN','REPLAY_REQUESTED','RELEASED','REJECTED')),correlation_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT transaction_timestamp(),resolved_at timestamptz);
CREATE INDEX quarantine_search_idx ON ouf_ingestion.ing_quarantine(state,created_at DESC);
CREATE TABLE ouf_ingestion.audit_event(event_id uuid PRIMARY KEY,event_type text NOT NULL,actor_subject text NOT NULL,actor_type text NOT NULL,resource_type text NOT NULL,resource_id text NOT NULL,correlation_id text NOT NULL,detail_json jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT transaction_timestamp());
CREATE FUNCTION ouf_ingestion.reject_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION USING ERRCODE='23001',MESSAGE='ingestion history is append-only';END$$;
CREATE TRIGGER attempt_append_only BEFORE UPDATE OR DELETE ON ouf_ingestion.processing_attempt FOR EACH ROW EXECUTE FUNCTION ouf_ingestion.reject_history_mutation();
CREATE TRIGGER lineage_append_only BEFORE UPDATE OR DELETE ON ouf_ingestion.ing_lineage FOR EACH ROW EXECUTE FUNCTION ouf_ingestion.reject_history_mutation();
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON ouf_ingestion.audit_event FOR EACH ROW EXECUTE FUNCTION ouf_ingestion.reject_history_mutation();
